"""Form Three French, Term One. Row 18 awaits teacher clarification; 16/32 are integration."""
from codex_support import *
from lessonlib import mcq
import banks_fr as B
F=fact

def unit(n,title,note,case,method,facts,**kw):
    concept_lesson("french","fr3-",n,title,note,case,method,facts,"francais",language="fr",**kw)

def conjugation(n,fn,tense,verbs):
    def form(person):
        return fn+"(v,"+person+")" if fn=="fr2PasseCompose" else "fr2With(p,"+fn+"(v,"+person+"))"
    return mcq(f"fr3-{n}-conjuguer",2,"Conjugue « {v} » à {tense}, avec « {fr2Pronoun(p)} ».",
       "{"+form("p")+"}",[("{"+form("(p+1)%8")+"}","personne"),("{"+form("(p+4)%8")+"}","personne2"),("{fr2With(p,v)}","infinitif")],
       ["Repère le sujet : {fr2Pronoun(p)}.","Choisis la forme de {v} à {tense} pour ce sujet.","La forme complète est {answer}."],
       vars={"v":{"pick":verbs},"p":{"int":[0,7]},"tense":tense},
       where=[fn+"(v,p) != "+fn+"(v,(p+1)%8)",fn+"(v,p) != "+fn+"(v,(p+4)%8)",fn+"(v,(p+1)%8) != "+fn+"(v,(p+4)%8)"],
       misc=[("personne","Cette terminaison correspond à un autre sujet. Accorde le verbe avec {fr2Pronoun(p)}."),("personne2","Tu as changé la personne grammaticale ; conserve le sujet demandé."),("infinitif","L’infinitif nomme le verbe, mais ici il faut le conjuguer au temps demandé.")],sources=["francais"],lang="fr")

unit(1,"L’adjectif qualificatif : emploi",
 "L’adjectif qualificatif exprime une caractéristique d’un nom ou d’un pronom. Épithète, il accompagne directement le nom ; attribut du sujet, il lui est relié par un verbe comme être. Il reçoit généralement le genre et le nombre du nom auquel il se rapporte. Sa place peut modifier le sens : un ancien professeur n’est pas nécessairement un professeur âgé. Observe donc la relation grammaticale et le contexte, pas seulement la position du mot.",
 "À Buea, Bih décrit une cour calme. Calme est épithète de cour. Dans la cour est calme, le même adjectif est attribut du sujet. Dans des cours propres, le nom pluriel commande {fr2Adj('propre','f',true)}. L’adjectif ne s’accorde pas avec le nom le plus proche par hasard : il faut retrouver celui qu’il qualifie.",
 "Trouve d’abord le nom qualifié, puis son genre et son nombre. Vérifie si l’adjectif accompagne ce nom ou passe par un verbe attributif. Certains adjectifs gardent la même forme au masculin et au féminin ; cela ne signifie pas qu’ils n’ont aucune relation d’accord.",[
 F("épithète","un adjectif directement rattaché au nom","Dans une cour calme, calme accompagne directement cour.","Tout adjectif après un nom est obligatoirement attribut.","L’attribut passe par un verbe attributif ; la seule position ne suffit pas."),F("attribut du sujet","un adjectif relié au sujet par un verbe attributif","Dans la cour est calme, calme caractérise le sujet à travers est.","Un attribut du sujet qualifie nécessairement un complément sans rapport.","Retrouve le sujet auquel le verbe relie la qualité."),F("accord","la relation de genre et de nombre entre le nom et l’adjectif","Le groupe des cours {fr2Adj('propre','f',true)} porte la marque du pluriel.","L’adjectif reçoit son nombre du mot placé le plus loin.","Il reçoit l’accord du nom qu’il qualifie."),F("effet de place","une différence de sens liée à la position de certains adjectifs","Un ancien professeur a cessé d’exercer cette fonction.","Ancien devant professeur signifie toujours très âgé.","Ici ancien signifie qui exerçait auparavant ; le contexte décide du sens.")])

unit(2,"Le passé composé : formation et emploi",
 "Le passé composé associe un auxiliaire au présent et un participe passé. Il présente notamment un fait accompli. Le choix entre avoir et être dépend du verbe et parfois de son emploi. Ne remplace pas le participe par l’infinitif. Avec être, les participes des verbes non pronominaux étudiés s’accordent avec le sujet. Cette leçon introduit la construction ; les accords particuliers avec avoir ne se réduisent pas à une règle automatique avec le sujet.",
 "Bih raconte une activité terminée : {fr2PasseCompose('travailler',3)}. Elle emploie avoir au présent et le participe {fr2Participle('travailler')}. Pour un déplacement accompli : {fr2PasseCompose('arriver',3)}. La forme d’arriver utilise être et l’accord féminin. Le temps composé forme un ensemble même si un adverbe s’intercale dans certains emplois.",
 "Repère le sujet et l’infinitif, choisis l’auxiliaire, conjugue cet auxiliaire au présent et ajoute le participe. Vérifie ensuite l’accord exigé. Pour le passé composé, ne conjugue pas simultanément le verbe lexical au présent et à l’infinitif.",[
 F("auxiliaire","le verbe avoir ou être portant personne et temps dans la construction","Dans {fr2PasseCompose('travailler',3)}, avoir porte la conjugaison.","Un auxiliaire ne change jamais selon le sujet.","L’auxiliaire se conjugue avec le sujet."),F("participe passé","la forme verbale associée à l’auxiliaire","Le participe de travailler est {fr2Participle('travailler')}.","Le participe de travailler est toujours travailler.","Distingue l’infinitif en -er et le participe en -é."),F("fait accompli","une action présentée comme achevée dans le contexte","{fr2PasseCompose('finir',3)} présente ici un travail terminé.","Le passé composé ne peut jamais présenter une action achevée.","Il sert couramment à présenter un fait accompli."),F("accord avec être","l’accord du participe avec le sujet pour les verbes non pronominaux étudiés","{fr2PasseCompose('arriver',7)} comporte un sujet féminin pluriel.","Avec être, un sujet féminin pluriel impose toujours un participe masculin singulier.","Le participe prend ici les marques du féminin et du pluriel.")],replacement={2:conjugation(2,"fr2PasseCompose","passé composé",["travailler","finir","arriver","partir"])})

def vocab(n,title,note,case,rows,method=None):
    unit(n,title,note,case,method or "Relis la phrase entière avant de choisir un mot. Vérifie sa catégorie grammaticale et la nuance voulue. Une proximité de sens n’autorise pas tous les remplacements. Emploie ensuite le mot dans une phrase originale et explique ton choix.",[F(*r) for r in rows])

vocab(3,"Les synonymes",
 "Des synonymes ont des sens proches dans un contexte donné. Ils ne sont pas toujours interchangeables : le registre, l’intensité et les mots voisins comptent. Une substitution réussie conserve l’idée voulue et la construction. Cherche un adjectif pour remplacer un adjectif, sauf si tu reconstruis toute la phrase. Un synonyme ne signifie pas le contraire et ne se définit pas par une simple ressemblance sonore.",
 "Dans un récit original situé à Bamenda, une élève est contente d’aider. Heureuse peut convenir ici. Une tâche difficile peut être décrite comme ardue dans un registre plus soutenu. Le remplacement doit rester adapté au lecteur ; rapide et pressé ne décrivent pas toujours la même chose.",[
 ("heureux","proche de content dans le contexte d’une satisfaction","Bih est contente de retrouver son amie ; elle en est heureuse.","Heureux signifie toujours triste.","Heureux exprime ici une satisfaction, non la tristesse."),
 ("ardue","proche de difficile pour une tâche exigeante","La tâche difficile est qualifiée d’ardue.","Ardue signifie toujours facile.","Une tâche ardue demande un effort."),
 ("paisible","proche de calme pour une ambiance sans agitation","Le jardin calme offre une ambiance paisible.","Paisible décrit obligatoirement une bagarre bruyante.","Paisible convient ici à l’absence d’agitation."),
 ("vaste","proche de grand pour une étendue importante","Une grande étendue est décrite comme vaste.","Vaste signifie étroit dans tous les contextes.","Vaste insiste ici sur une étendue importante.")])

unit(4,"La ponctuation",
 "La ponctuation organise l’écrit et aide à comprendre les relations entre les idées. Le point termine une phrase déclarative ; le point d’interrogation marque une question directe ; les deux-points peuvent annoncer une explication ou une liste ; la virgule sépare notamment les éléments d’une énumération. Une virgule ne doit pas séparer au hasard le sujet de son verbe. Les signes ne sont pas seulement des pauses respiratoires : ils contribuent à la structure et au sens.",
 "Texte original : Bih prépare son sac : cahier, livre et règle. Le sac est prêt. Ayuk demande : « Où est la règle ? » La liste suit les deux-points ; les éléments sont séparés ; la question directe porte le signe qui convient. Une ponctuation différente pourrait brouiller qui parle ou ce qui est demandé.",
 "Repère les limites des phrases, les listes et les paroles rapportées. Choisis le signe selon la fonction. Relis pour vérifier les majuscules et l’espacement français avant les signes doubles. Ne place pas un point d’interrogation uniquement parce qu’un mot comme pourquoi apparaît dans une interrogation indirecte.",[
 F("point","le signe terminant une phrase déclarative ordinaire","Le sac est prêt.","Une phrase déclarative doit toujours finir par une virgule isolée.","Le point marque ici la fin de la phrase."),F("point d’interrogation","le signe d’une question directe","Où est la règle ?","Toute phrase contenant où est une question directe.","Le sens et la structure décident ; je sais où elle est n’est pas une question directe."),F("deux-points","un signe pouvant annoncer une liste ou une explication","Voici le matériel : livre, cahier et règle.","Les deux-points suppriment le besoin d’une liste annoncée.","Ils annoncent ici ce que la suite précise."),F("virgule","un signe séparant notamment des éléments d’une énumération","Le sac contient un livre, un cahier et une règle.","On sépare toujours le sujet de son verbe par une virgule.","Ne coupe pas arbitrairement le lien entre sujet et verbe.")])

for n,case in [(5,"Texte original : À Bamenda, Bih accompagne sa tante au marché. Un panier reste près d’un étal. Bih demande à la vendeuse à qui il appartient. La vendeuse reconnaît le panier d’une cliente et le met de côté. Bih continue ses achats. Le texte indique une demande et une action prudente ; il ne précise ni le nom de la cliente ni le prix des achats."),(22,"Texte original : À Douala, un club prépare une cour plus propre. Ayuk dessine une affiche, Bih propose de séparer les déchets selon les consignes de l’école. Une enseignante vérifie le projet avant l’activité. Le groupe décide de ne pas toucher aux déchets coupants ou inconnus. Le texte présente une préparation, pas le compte rendu d’un résultat déjà obtenu.")]:
    unit(n,"Lecture : comprendre un texte original du module",
      "Comprendre un texte demande de relever ce qui est dit, de relier les indices et de distinguer une déduction d’une invention. L’idée principale résume l’ensemble ; un détail répond à une question précise. Une inférence doit s’appuyer sur des éléments du passage. Si l’information manque, indique qu’elle n’est pas précisée au lieu de lui attribuer une valeur imaginaire. Ce passage original remplace seulement un support de lecture, pas une œuvre littéraire prescrite.",case,
      "Lis le passage entièrement, puis formule son sujet. Pour chaque réponse, retrouve un indice. Une question de cause demande pourquoi ; une question de lieu demande où. En résumant, conserve l’action principale sans ajouter de noms, de prix ou de résultats absents.",[
      F("information explicite","un renseignement directement donné par le texte","Le lecteur reprend un lieu effectivement nommé dans le passage.","Une information explicite est toujours inventée par le lecteur.","Elle figure directement dans le passage."),F("inférence justifiée","une conclusion appuyée sur les indices du passage","Le lecteur explique une intention en citant les actions décrites.","Toute supposition personnelle est une inférence prouvée.","Une inférence doit être soutenue par des indices."),F("idée principale","le sens général qui rassemble les actions importantes","Le lecteur résume l’action centrale sans recopier chaque détail.","Un détail sans rapport suffit toujours à résumer tout le texte.","Le résumé doit représenter l’ensemble pertinent."),F("information absente","un renseignement que le passage ne permet pas de déterminer","Le lecteur refuse d’inventer un prix non indiqué.","Un prix absent doit être remplacé par un montant deviné.","Dire non précisé est plus fidèle que fabriquer une information.")],
      replacement={2:B.QA(f"fr3-{n}-lire",2,case+"\n{X.q}",[
        dict(q=q,r=r,w=w,e=e,y=y) for q,r,w,e,y in ([
         ("Où Bih accompagne-t-elle sa tante ?","Au marché de Bamenda.",["Dans un hôpital de Douala.","Dans un train.","Le texte ne donne aucun lieu."],["Le texte nomme un marché à Bamenda, pas cet hôpital.","Aucun train n’est mentionné.","Le lieu figure dans la première phrase."],"Le début situe la scène au marché de Bamenda."),
         ("Pourquoi la vendeuse peut-elle mettre le panier de côté ?","Elle reconnaît le panier d’une cliente.",["Elle sait qu’il appartient à Bih.","Elle a lu le prix du panier.","Elle ne voit aucun panier."],["Le texte l’attribue à une cliente, pas à Bih.","Le prix n’est pas donné et n’explique pas cette action.","Le panier est explicitement présent."],"La reconnaissance précède la mise de côté dans le passage."),
         ("Quelle information manque ?","Le nom de la cliente.",["La ville de la scène.","La présence de la tante.","La demande de Bih."],["Bamenda est nommé.","La tante est mentionnée au début.","Le passage rapporte la demande de Bih."],"Le texte dit expressément que le nom n’est pas précisé."),
         ("Quel résumé reste fidèle au passage ?","Bih signale un panier et la vendeuse le met de côté.",["Bih vole le panier.","La vendeuse vend le panier à Bih.","La tante ouvre un nouvel étal."],["Aucun vol n’est décrit.","Aucune vente du panier n’est rapportée.","Le texte n’indique pas que la tante ouvre un étal."],"Le résumé conserve la demande puis la mise de côté, sans inventer d’action.")]
        if n==5 else [
         ("Que prépare le club ?","Une cour plus propre.",["Un examen médical.","Une nouvelle gare.","Un concert déjà terminé."],["Le texte prépare un projet de cour, pas des soins.","Aucune gare n’est évoquée.","Il s’agit d’une préparation, pas d’un concert achevé."],"Le projet de propreté est indiqué au début."),
         ("Que propose Bih ?","Séparer les déchets selon les consignes.",["Toucher tous les objets inconnus.","Annuler toute vérification.","Acheter des billets."],["Le groupe évite les déchets inconnus.","L’enseignante vérifie justement le projet.","Aucun billet n’est mentionné."],"Le passage attribue cette proposition à Bih."),
         ("Quel indice montre une précaution ?","Le groupe décide de ne pas toucher les déchets coupants.",["Tous les déchets sont déjà recyclés.","Ayuk exerce comme médecin.","Personne ne vérifie le projet."],["Le texte ne rapporte pas un recyclage déjà accompli.","Ayuk dessine une affiche ; aucun métier n’est annoncé.","Une enseignante vérifie le projet."],"Cette décision évite une manipulation risquée dans le projet."),
         ("Quel résultat peut-on affirmer ?","Le projet a été préparé, mais le résultat final n’est pas donné.",["La cour est déjà entièrement nettoyée.","Le club a gagné un prix.","Tous les déchets ont disparu."],["Le texte distingue préparation et résultat.","Aucun prix n’est annoncé.","La disparition des déchets n’est pas rapportée."],"La dernière phrase limite explicitement ce qui est établi.")])],["francais"])})

def writing(n,title,note,model,method,facts,prompt,checks):
    unit(n,title,note,"Modèle original : "+model,method,facts,paper=paper(prompt,[model],checks))

for n,model in [(6,"Bih est une camarade attentive. Ses gestes sont calmes et son regard suit la personne qui parle. Pendant le travail de groupe, elle laisse chacun expliquer son idée. Son attention se voit donc dans ses actions plutôt que dans une simple liste de qualités."),(23,"Au marché imaginaire de Buea, un vendeur range ses paniers avec soin. Sa chemise claire contraste avec les tissus suspendus derrière lui. Il écoute la question d’une cliente avant de répondre. Le portrait associe détails visibles et comportement, sans prétendre connaître toutes ses pensées.")]:
    writing(n,"Description et portrait", "Un portrait décrit une personne selon une organisation choisie. Les traits physiques concernent l’apparence ; les traits moraux concernent le caractère. Pour éviter un jugement gratuit, relie une qualité à une action observable. Choisis un point de vue et des détails utiles. Les adjectifs s’accordent avec les noms qu’ils qualifient. Une apparence ne prouve ni la valeur ni le caractère d’une personne : le portrait ne doit pas transformer un détail physique en insulte.",model,
      "Présente la personne, organise les détails et termine par une impression soutenue par le texte. Relis les accords et évite la répétition de il est ou elle est. Tu peux décrire un personnage imaginaire pour préserver la vie privée.",[
      F("trait physique","un détail d’apparence observable","Le portrait mentionne une chemise claire.","La couleur d’une chemise prouve l’honnêteté d’une personne.","Un détail visible ne démontre pas une qualité morale."),F("trait moral","une caractéristique du comportement ou du caractère","L’attention est appuyée par l’écoute d’une question.","Le caractère se définit uniquement par la taille.","Appuie un trait moral sur le comportement pertinent."),F("organisation","un ordre choisi pour guider la description","Le texte présente la personne puis des détails significatifs.","Une description claire exige des détails sans aucun ordre.","Un parcours organisé aide le lecteur à se représenter la personne."),F("détail significatif","un élément qui contribue à l’impression du portrait","Un geste d’écoute soutient l’idée d’attention.","Tout détail sans rapport améliore nécessairement le portrait.","Choisis les détails en fonction de l’effet recherché.")],
      "Rédige le portrait original d’un personnage imaginaire au Cameroun. Organise ses traits physiques et son comportement sans stéréotype ni information privée.",["Je présente clairement le personnage.","Mes détails suivent un ordre et soutiennent une impression.","Je vérifie les accords et j’évite les jugements fondés sur l’apparence seule."])

vocab(7,"Les antonymes : suite",
 "Des antonymes expriment des sens opposés sur un même axe. Le contexte détermine l’opposition utile : clair peut s’opposer à sombre pour la lumière, mais à obscur pour une explication. Tous les mots n’ont pas un antonyme unique. Un préfixe peut former un contraire, mais il ne s’ajoute pas mécaniquement à tous les mots. Conserve la catégorie grammaticale et le sens de la phrase.",
 "Dans une salle imaginaire, une porte ouverte devient fermée. Un passage large s’oppose à un passage étroit. Une réponse polie peut être opposée à une réponse impolie. Ces oppositions ne sont pas des mots proches : elles changent la caractéristique décrite.",[
 ("fermé","contraire d’ouvert pour une porte","Une porte qui n’est plus ouverte est fermée.","Fermé est synonyme d’ouvert dans cet exemple.","Les états décrits sont opposés."),("étroit","contraire de large pour un passage","Un passage de faible largeur est étroit.","Étroit signifie toujours très large.","Les deux mots s’opposent sur la largeur."),("impoli","contraire de poli pour un comportement","Une réponse irrespectueuse est impolie.","Tous les contraires se forment en ajoutant exactement le même préfixe.","Les formations varient ; vérifie le mot."),("sombre","contraire de clair pour un lieu peu éclairé","La pièce peu éclairée est sombre.","Clair garde exactement le même contraire dans tous ses sens.","Choisis l’opposition selon le sens de clair dans la phrase.")])

unit(8,"Accord du participe passé avec être",
 "Avec l’auxiliaire être, le participe passé des verbes non pronominaux étudiés s’accorde en genre et en nombre avec le sujet. Le sujet peut être éloigné : il faut le retrouver. Le féminin ajoute souvent -e et le pluriel -s, sous réserve de la forme du participe. Les verbes pronominaux demandent une analyse particulière et ne sont pas tous couverts par cette règle simple. Ne confonds pas la personne de l’auxiliaire avec les marques du participe.",
 "Pour arriver, compare {fr2PasseCompose('arriver',2)}, {fr2PasseCompose('arriver',3)}, {fr2PasseCompose('arriver',6)} et {fr2PasseCompose('arriver',7)}. La terminaison du participe indique le genre et le nombre du sujet. Le changement de sujet peut aussi modifier l’auxiliaire ; les deux vérifications sont nécessaires.",
 "Souligne le sujet, relève son genre et son nombre, puis vérifie auxiliaire et participe séparément. N’accorde pas le participe avec un complément de lieu. Pour nous et vous, le contexte précise le genre ; les exercices emploient des pronoms non ambigus.",[
 F("masculin singulier","l’accord avec il dans le modèle","{fr2PasseCompose('partir',2)} correspond à il.","Il impose toujours la marque du féminin pluriel.","Le pronom il est ici masculin singulier."),F("féminin singulier","l’accord avec elle dans le modèle","{fr2PasseCompose('partir',3)} correspond à elle.","Elle exige ici l’absence de toute marque féminine.","Le participe reçoit la marque du féminin singulier."),F("masculin pluriel","l’accord avec ils dans le modèle","{fr2PasseCompose('partir',6)} correspond à ils.","Ils représente toujours un sujet singulier.","Le participe reçoit ici le pluriel masculin."),F("féminin pluriel","l’accord avec elles dans le modèle","{fr2PasseCompose('partir',7)} correspond à elles.","Elles commande un participe masculin singulier.","Le participe prend ici féminin et pluriel.")],replacement={2:conjugation(8,"fr2PasseCompose","passé composé",["arriver","partir","venir","rester"])})

unit(9,"Les conjonctions de coordination",
 "Une conjonction de coordination relie des éléments de même fonction ou des propositions. Et ajoute, mais oppose, ou présente une alternative, car introduit une explication dans les modèles étudiés. La relation voulue compte plus qu’une liste apprise par cœur. Ne confonds pas ou sans accent, qui propose un choix, avec où, qui peut indiquer un lieu. Un mot de liaison ne rend pas automatiquement logique une relation absente du texte.",
 "Bih apporte un livre et un cahier. Ayuk veut venir, mais il doit finir une tâche. Le groupe choisit la salle ou la cour. Il se réunit dedans, car il pleut. Chaque liaison a une fonction différente : remplacer car par mais modifierait la relation annoncée.",
 "Repère les éléments reliés et formule la relation : addition, opposition, choix ou explication. Choisis ensuite la conjonction adaptée. Vérifie que les deux parties se construisent correctement et que la ponctuation soutient la lecture.",[
 F("et","une liaison d’addition","Bih apporte un cahier et un livre.","Et indique nécessairement une opposition.","Et ajoute ici un élément."),F("mais","une liaison d’opposition","Ayuk veut venir, mais une tâche le retient.","Mais signifie toujours exactement la même chose que car.","Mais oppose les deux idées ; car explique."),F("ou","une liaison présentant une alternative","Le groupe choisit la salle ou la cour.","Ou et où ont toujours la même fonction.","Ou propose un choix ; où porte un accent et a un autre emploi."),F("car","une liaison donnant une explication","Le groupe reste dedans, car il pleut.","Car retire toute relation explicative.","La pluie donne ici la raison du choix.")])

for n,model in [(10,"Un matin, Bih cherche un livre emprunté. Le sac reste vide malgré ses recherches. Elle se rappelle alors la séance du club et retourne demander à l’enseignante. Le livre l’attend sur une étagère. Bih remercie l’enseignante et note désormais l’endroit où elle range ses emprunts."),(29,"Ayuk prépare une affiche pour le club. Une averse mouille le premier dessin resté près d’une fenêtre. Il demande de l’aide et reprend le travail sur une feuille sèche. Le groupe installe ensuite l’affiche à l’abri. L’incident change la préparation, mais le récit se termine par une solution cohérente.")]:
    writing(n,"La narration : organiser un récit", "Un récit raconte des événements liés. Il présente une situation initiale, un événement qui la modifie, des actions et une issue. Les connecteurs temporels guident le lecteur. Le choix des temps distingue notamment les circonstances et les événements accomplis. Un récit inventé doit rester cohérent avec ses propres personnages et lieux ; il n’a pas besoin d’être le compte rendu d’une expérience privée.",model,
      "Prépare un petit plan avant de rédiger : qui, où, difficulté, actions, résultat. Conserve le même point de vue et vérifie à qui renvoient les pronoms. La conclusion doit répondre à ce qui a été engagé dans le récit, sans ajouter un sujet sans rapport.",[
      F("situation initiale","le contexte de départ du récit","Le début présente le personnage et son activité.","Le lecteur doit deviner tous les personnages sans indice.","Un début apporte les repères nécessaires."),F("élément perturbateur","l’événement qui modifie la situation de départ","Un objet manque ou un dessin est abîmé.","Un événement perturbateur ne change jamais la situation.","Il déclenche ici une difficulté à résoudre."),F("enchaînement","le lien logique et temporel entre les actions","Le personnage cherche une solution après avoir rencontré la difficulté.","Des actions sans lien garantissent un récit clair.","Les étapes doivent pouvoir être suivies."),F("dénouement","l’issue de la difficulté racontée","La fin montre la solution apportée au problème.","Le dénouement doit ignorer complètement la difficulté.","L’issue se rattache au problème du récit.")],
      "Écris un récit original situé dans un cadre camerounais de ton choix. Présente un personnage, une difficulté, les actions liées et une issue cohérente.",["Le lecteur connaît le contexte et la difficulté.","Les actions suivent un ordre compréhensible.","Je vérifie les temps, les pronoms et la cohérence de la fin."])

for n,title,model in [(11,"Préparer un sketch dialogué","Dialogue original : Bih : « Cette salle est-elle libre ? » Ayuk : « Le club l’utilise maintenant. » Bih : « Pourrions-nous travailler dans la cour à l’ombre ? » Ayuk : « Demandons d’abord à l’enseignante. » Le cadre et les rôles restent compréhensibles sans décor complexe."),(21,"Préparer une récitation ou un jeu de rôle","Petit texte original : « Notre cour accueille nos pas ; chaque geste y laisse sa trace. Un papier rejoint le panier, et le lieu retrouve sa place. » On peut préparer les groupes de sens puis expliquer le message avec ses propres mots. Ce texte n’est pas une œuvre prescrite.")]:
    unit(n,title,"La préparation écrite d’un oral clarifie le message, les rôles et les groupes de sens. Une réplique correspond à une prise de parole ; une didascalie donne une indication de jeu ; l’articulation rend les mots distincts ; l’intonation contribue à l’intention. Le texte affiché permet de préparer ces éléments, mais il ne peut ni entendre ni noter la voix. Une récitation réelle ou un chant nécessite un modèle et une pratique avec un enseignant.",model,
      "Repère qui parle, ce que la personne veut et où les idées se séparent. Prépare une diction compréhensible sans transformer chaque mot en cri. Pour un chant, la mélodie doit venir d’un modèle approprié ; aucune hauteur musicale n’est évaluée ici.",[
      F("réplique","une prise de parole d’un personnage","Dans un dialogue, une ligne attribuée à Bih constitue sa prise de parole.","Une réplique ne peut appartenir à aucun personnage.","L’attribution aide à comprendre qui parle."),F("didascalie","une indication de jeu distincte des paroles","La mention à voix calme indique comment jouer la scène.","Toute indication de jeu doit forcément être prononcée comme une réplique.","Une didascalie guide le jeu, sans être nécessairement dite."),F("groupe de sens","un ensemble de mots formant une unité compréhensible à l’oral","Le lecteur prépare une pause à la fin d’une idée.","Une pause au milieu de chaque mot facilite toujours le sens.","Les pauses doivent respecter les unités de sens."),F("intention","le but expressif de la prise de parole","Une demande polie cherche une réponse sans agresser.","Toutes les phrases ont obligatoirement la même intention.","Demander, informer et exprimer une émotion appellent des intentions différentes.")])

vocab(12,"Les consonnes doubles",
 "Certaines graphies comportent une consonne doublée. Il faut apprendre les mots et leurs familles : la prononciation seule ne permet pas toujours de compter les lettres. Une double consonne n’impose pas une double syllabe. Observe la position du doublement et recopie le mot entier, puis vérifie-le dans une source linguistique. Ne généralise pas une graphie à tous les mots qui commencent de la même façon.",
 "Un message original contient adresse, village, personne et attention. On repère ss dans adresse, ll dans village, nn dans personne et tt dans attention. On peut masquer le modèle, écrire le mot puis comparer les lettres ; ce travail est différent d’un test d’écoute.",[
 ("adresse","un mot comportant ss dans sa graphie","Bih relit adresse et repère ss.","Adresse contient nécessairement un seul s.","Le modèle comporte ss."),("village","un mot comportant ll dans sa graphie","Ayuk repère ll dans village.","Village exige deux g dans ce modèle.","Le doublement porte sur l, pas sur g."),("personne","un mot comportant nn dans sa graphie","La classe vérifie nn dans personne.","Personne s’écrit sans double consonne.","Le mot comporte nn."),("attention","un mot comportant tt dans sa graphie","Le lecteur souligne tt dans attention.","Attention exige deux n à la fin.","Le doublement étudié porte sur t.")])

unit(13,"L’accord de l’adjectif dans le groupe nominal",
 "Le nom noyau donne son genre et son nombre à l’adjectif qui le qualifie. Le déterminant aide à repérer le nombre, mais il faut connaître le genre du nom. Beaucoup d’adjectifs ajoutent -e au féminin et -s au pluriel ; d’autres changent davantage ou gardent la même forme. La règle ne consiste donc pas à ajouter automatiquement toutes les lettres possibles. Vérifie la forme propre à l’adjectif.",
 "Compare une cour {fr2Adj('propre','f',false)} et des cours {fr2Adj('propre','f',true)} ; un arbre {fr2Adj('grand','m',false)} et des maisons {fr2Adj('grand','f',true)}. Propre possède déjà un e final au masculin. Ajouter un autre e pour fabriquer le féminin serait une application aveugle de la règle.",
 "Identifie nom, genre et nombre, puis choisis la forme de l’adjectif. Relis tout le groupe nominal. Si l’adjectif ne change pas à l’écrit pour un trait donné, conserve quand même l’analyse grammaticale qui justifie l’accord.",[
 F("nom noyau","le nom qui commande l’accord dans le groupe étudié","Dans des cours propres, cours commande le pluriel.","L’adjectif choisit son nombre au hasard.","Il dépend du nom qu’il qualifie."),F("genre","la catégorie masculin ou féminin du nom","Cour est un nom féminin dans ce groupe.","La terminaison visible d’un seul mot suffit à connaître tous les genres.","Le genre lexical doit être vérifié lorsqu’il est inconnu."),F("nombre","la distinction entre singulier et pluriel","Des cours désigne ici un groupe pluriel.","Des commande obligatoirement le singulier.","Des introduit ici un nom pluriel."),F("forme particulière","une réalisation d’accord propre à un adjectif","Le féminin de propre reste {fr2Adj('propre','f',false)}.","On ajoute toujours un e supplémentaire à propre au féminin.","Propre possède déjà cette terminaison au masculin et au féminin.")],replacement={2:mcq("fr3-13-accord",2,"Accorde « {a} » au {fr2GenderNumber(g,pl)}.","{fr2Adj(a,g,pl)}",[("{fr2Adj(a,fr2OtherGender(g),pl)}","genre"),("{fr2Adj(a,g,!pl)}","nombre"),("{fr2Adj(a,fr2OtherGender(g),!pl)}","deux")],["Relève le genre et le nombre demandés.","La forme est {answer}."],vars={"a":{"pick":["petit","grand","vert","bleu","blanc"]},"g":{"pick":["m","f"]},"pl":{"pick":[True,False]}},misc=[("genre","Le nombre convient, mais pas le genre demandé."),("nombre","Le genre convient, mais pas le nombre demandé."),("deux","Cette forme change à la fois le genre et le nombre demandés.")],sources=["francais"],lang="fr")})

unit(14,"L’imparfait : formation et emploi",
 "L’imparfait présente notamment une habitude passée, une description ou une action en cours dans le passé. Pour beaucoup de verbes, on prend le radical de nous au présent sans -ons et on ajoute -ais, -ais, -ait, -ions, -iez, -aient. Être emploie le radical ét-. Certaines graphies conservent un e ou une cédille selon la voyelle suivante. Le choix du temps dépend du sens, pas seulement de la présence du mot hier.",
 "Dans un récit original, Bih évoque une habitude : chaque soir, {fr2With(3,fr2Imparfait('travailler',3))}. Pour le décor : {fr2With(2,fr2Imparfait('être',2))} calme. Ces formes ne donnent pas à elles seules une liste d’événements achevés. Elles installent une durée, un état ou une répétition selon la phrase.",
 "Trouve le radical approprié et la personne. Vérifie ensuite l’usage : habitude, description ou action en cours. Ne remplace pas systématiquement tous les passés composés d’un récit par des imparfaits, car cela change la façon de présenter les événements.",[
 F("habitude passée","une action répétée dans un cadre passé","Chaque soir, {fr2With(3,fr2Imparfait('travailler',3))} au même endroit.","Une habitude passée ne peut jamais être exprimée à l’imparfait.","L’imparfait convient couramment à la répétition passée."),F("description passée","la présentation d’un état ou d’un décor dans le passé","Le lieu {fr2Imparfait('être',2)} calme dans le récit.","Toute description passée doit obligatoirement être au futur.","L’imparfait peut installer le décor passé."),F("radical","la base à laquelle on ajoute les terminaisons","Pour travailler, le modèle utilise la base travaill-.","Le radical de tous les verbes à l’imparfait est toujours ét-.","Ét- est le radical particulier d’être, pas de tous les verbes."),F("terminaison","la partie qui marque notamment la personne à ce temps","Avec nous, le modèle donne {fr2Imparfait('travailler',4)}.","Nous impose toujours la terminaison -ait.","À l’imparfait, nous prend -ions.")],replacement={2:conjugation(14,"fr2Imparfait","imparfait",["travailler","finir","être","manger"])})

vocab(15,"Exprimer la sympathie et l’antipathie",
 "On peut exprimer une appréciation ou un désaccord sans attaquer la dignité d’une personne. La sympathie peut se manifester par une parole accueillante ; l’antipathie désigne un sentiment défavorable, mais n’autorise ni insulte ni discrimination. Distingue un sentiment, un jugement sur un comportement et une règle de conduite. Pour discuter en classe, utilise des personnages fictifs et explique les raisons sans répandre de rumeurs.",
 "Dialogue original : Bih apprécie l’accueil d’une camarade. Ayuk dit qu’un comportement moqueur lui déplaît. Bih propose d’en parler calmement. Ils décrivent des actes précis, sans conclure qu’une origine ou une apparence rend une personne mauvaise.",[
 ("sympathie","un sentiment favorable envers une personne","Bih apprécie l’accueil aimable de sa camarade.","La sympathie signifie toujours le rejet d’une personne.","Elle désigne ici une disposition favorable."),("antipathie","un sentiment défavorable envers une personne","Un personnage éprouve de l’antipathie sans l’exprimer par une insulte.","Ressentir de l’antipathie oblige à humilier quelqu’un.","Un sentiment n’autorise pas l’humiliation."),("désaccord","une opposition à une idée ou à un comportement","Ayuk critique une moquerie précise.","Désapprouver une idée impose de détester toute la personne.","On peut discuter un acte en respectant la personne."),("courtoisie","une manière respectueuse de s’adresser à autrui","Bih demande calmement une explication.","La courtoisie exige de renoncer à toute critique.","Une critique peut être claire et respectueuse.")])

unit(17,"Le pluriel des noms en -al et -ail",
 "Beaucoup de noms en -al forment leur pluriel en -aux, mais bal, carnaval et festival gardent notamment -s. La plupart des noms en -ail prennent -s ; certains, comme travail et vitrail, ont un pluriel en -aux. Il faut apprendre les exceptions plutôt que transformer automatiquement toute finale. Le déterminant pluriel s’accorde avec le nom choisi. Un mot ressemblant à un autre n’appartient pas nécessairement au même modèle.",
 "À partir des noms du modèle : cheval → {fr2NounPlural('cheval')}, festival → {fr2NounPlural('festival')}, détail → {fr2NounPlural('détail')}, travail → {fr2NounPlural('travail')}. La comparaison révèle un modèle fréquent et des exceptions. Le pluriel doit être vérifié mot par mot lorsque le nom n’est pas connu.",
 "Repère la finale, propose le modèle et vérifie si le mot fait exception. Ne confonds pas les deux séries : tous les -ail ne deviennent pas -aux et tous les -al ne prennent pas -s.",[
 F("modèle -al vers -aux","le pluriel fréquent illustré par cheval","Cheval devient {fr2NounPlural('cheval')}.","Tous les noms en -al se terminent obligatoirement par -als au pluriel.","Cheval suit ici le modèle en -aux."),F("exception en -als","le pluriel illustré par festival","Festival devient {fr2NounPlural('festival')}.","Festival a obligatoirement pour pluriel festivaux.","Festival conserve sa base et prend -s."),F("modèle -ail vers -ails","le pluriel fréquent illustré par détail","Détail devient {fr2NounPlural('détail')}.","Tous les noms en -ail deviennent -aux.","La plupart prennent -s ; détail suit ce modèle."),F("exception -ail vers -aux","le pluriel illustré par travail","Travail devient {fr2NounPlural('travail')}.","Le pluriel de travail est toujours travails dans le modèle étudié.","Travail fait partie des exceptions en -aux.")],replacement={2:mcq("fr3-17-pluriel",2,"Choisis le pluriel de « {n} ».","{fr2NounPlural(n)}",[("{fr2NounNaive(n)}","modele"),("{n}","singulier"),("{n+'es'}","lettres")],["Vérifie le modèle et ses exceptions.","Le pluriel attendu est {answer}."],vars={"n":{"pick":["cheval","festival","détail","travail","journal","bal","vitrail"]}},misc=[("modele","Ce mot ne suit pas le modèle que tu as appliqué ; vérifie les exceptions."),("singulier","Cette forme reste au singulier."),("lettres","On ne forme pas ce pluriel en ajoutant arbitrairement -es.")],sources=["francais"],lang="fr")})

vocab(19,"Les lettres muettes à l’intérieur des mots",
 "Une lettre peut être écrite sans correspondre à un son prononcé dans le modèle étudié. Une consonne muette ne disparaît donc pas de l’orthographe. L’observation des familles et le dictionnaire aident à mémoriser la graphie. La prononciation varie parfois selon le contexte ou l’accent : cette leçon porte sur quelques modèles écrits et non sur une règle universelle concernant toutes les consonnes. Le libellé « sept fonctions » du spine reste à vérifier par l’enseignant.",
 "On compare les graphies rhume, théâtre, compter et automne. Le h intérieur des deux premiers ne correspond pas à un son autonome ; le p de compter et le n d’automne sont muets dans les modèles usuels considérés. Il faut néanmoins les conserver à l’écrit. Une pratique audio avec l’enseignant complète cette observation.",[
 ("rhume","un modèle écrit comportant un h intérieur sans son autonome","On conserve le h de rhume même sans son autonome.","Une lettre muette doit toujours être supprimée à l’écrit.","L’orthographe conserve cette lettre."),("théâtre","un modèle écrit avec h non prononcé dans th","Le groupe th de théâtre ne donne pas un son h séparé.","Théâtre se prononce nécessairement avec un souffle h séparé.","Le h ne correspond pas ici à un son autonome."),("compter","un modèle dont le p intérieur est muet","Le lecteur repère le p écrit dans compter.","Le p de compter est nécessairement prononcé dans le modèle courant.","Le p reste écrit sans être prononcé dans ce modèle."),("automne","un modèle dont le n est muet","Le n d’automne est conservé dans la graphie.","Le n d’automne doit être supprimé de la graphie parce qu’il est muet.","Prononciation et orthographe ne se confondent pas.")])

vocab(20,"Maladies : épidémie, pandémie et endémie",
 "Ces termes décrivent la présence et l’étendue d’une maladie dans une population, pas la valeur d’une personne. Une endémie correspond à une présence habituelle dans une zone ; une épidémie à une augmentation au-delà de ce qui est attendu dans une population et une période données ; une pandémie à une épidémie largement étendue à l’échelle internationale. L’étendue ne suffit pas à décrire la gravité de chaque cas. Le diagnostic relève d’un professionnel de santé.",
 "Dans des situations fictives, un rapport décrit une présence habituelle dans une zone, puis une hausse inhabituelle de cas. Un autre suit une propagation internationale très large. Le lecteur classe les descriptions sans inventer de seuil numérique ni annoncer une situation sanitaire actuelle au Cameroun.",[
 ("endémie","la présence habituelle d’une maladie dans une zone donnée","Un rapport fictif décrit une présence durable attendue dans une zone.","Endémique signifie sans danger pour toute personne.","La présence habituelle ne supprime pas les conséquences possibles."),("épidémie","une augmentation de cas au-delà de l’attendu dans une population et une période","Le rapport fictif relève une hausse inhabituelle de cas.","Une épidémie exige que tous les habitants soient malades.","Elle concerne un excès par rapport à l’attendu, pas nécessairement toute la population."),("pandémie","une épidémie largement propagée à l’échelle internationale","Le modèle décrit une propagation internationale très étendue.","Pandémie signifie obligatoirement que chaque cas est plus grave que tout autre.","Le terme porte sur l’étendue, pas sur une comparaison automatique des cas."),("diagnostic","l’identification médicale d’une affection par une personne compétente","Un professionnel évalue une situation individuelle.","Un exercice de vocabulaire suffit à diagnostiquer un camarade.","Le classement lexical ne remplace pas une évaluation médicale.")])

vocab(24,"Les sites touristiques : décrire un lieu",
 "Décrire un site demande un nom, une localisation vérifiée, des caractéristiques et une raison de l’intérêt présenté. Distingue un site naturel, un patrimoine culturel et une installation d’accueil. Au Cameroun, le ministère chargé du tourisme présente notamment les lacs jumeaux de Manengouba, la grotte de Ngog-lituba et le site de Mindif. Cette leçon apprend le vocabulaire descriptif ; elle ne fournit ni itinéraire, ni tarifs, ni avis de sécurité actuels.",
 "Un dépliant scolaire original présente un lieu par sa nature puis par son intérêt. Il distingue ce qui peut être observé d’une formule publicitaire comme le meilleur lieu du monde. Les noms réels cités sont des exemples documentaires ; les horaires et les conditions de visite doivent être vérifiés avant un déplacement.",[
 ("site naturel","un lieu dont l’intérêt porte notamment sur le milieu physique","Un dépliant décrit un paysage de lacs.","Tout paysage est obligatoirement un bâtiment construit.","Un milieu naturel et un édifice ne sont pas la même catégorie."),("patrimoine culturel","des éléments auxquels une communauté reconnaît une valeur culturelle","Un texte explique l’intérêt d’un objet ou d’un bâtiment transmis.","Le patrimoine culturel ne peut avoir aucun lien avec les communautés.","La valeur culturelle implique une relation aux personnes et à leur histoire."),("localisation","l’indication vérifiée de la situation d’un lieu","Le rédacteur vérifie où se trouve le site avant de l’indiquer.","Une localisation inventée rend un dépliant plus exact.","Une information géographique doit être vérifiée."),("formule promotionnelle","une expression destinée à valoriser un lieu","Le meilleur lieu du monde exprime une appréciation publicitaire.","Un superlatif publicitaire prouve une comparaison scientifique complète.","Une formule persuasive ne vaut pas une preuve objective.")])

unit(25,"Les adverbes de manière",
 "Un adverbe de manière précise comment une action se réalise. Il est invariable. Beaucoup se forment sur le féminin de l’adjectif suivi de -ment ; d’autres suivent une autre graphie. Prudence : l’adverbe ne qualifie pas le nom comme un adjectif et ne prend pas son pluriel. La formation doit être vérifiée, surtout pour les mots en -ant, -ent et les formes particulières.",
 "Bih répond {fr2Adverb('lent')}, Ayuk parle {fr2Adverb('poli')}, et le groupe agit {fr2Adverb('prudent')}. Ces mots précisent la manière de répondre, parler ou agir. Comparons une réponse polie et répondre {fr2Adverb('poli')} : la fonction change, donc la forme aussi.",
 "Repère le verbe modifié, demande comment et choisis l’adverbe. Vérifie la formation au lieu d’ajouter -ment sans réflexion. Ne lui donne pas de marque de genre ou de nombre.",[
 F("manière","la façon dont se déroule l’action","La question comment porte sur la façon de faire.","La manière signifie toujours combien d’objets existent.","Comment vise la façon ; combien vise une quantité."),F("invariabilité","l’absence d’accord de l’adverbe en genre et en nombre","Un même adverbe accompagne un sujet singulier ou pluriel.","Un adverbe prend toujours -s avec un sujet pluriel.","L’adverbe ne s’accorde pas avec le sujet."),F("formation régulière","une construction fréquente sur le féminin suivi de -ment","Lent donne {fr2Adverb('lent')} dans le modèle.","On ajoute toujours -ment à n’importe quel mot sans changement.","La base et les exceptions doivent être vérifiées."),F("forme particulière","une graphie qui nécessite une règle ou une mémorisation adaptée","Prudent donne {fr2Adverb('prudent')}.","Prudent donne obligatoirement prudentement.","Les adjectifs en -ent donnent souvent un adverbe en -emment.")],replacement={2:mcq("fr3-25-forme",2,"Forme l’adverbe de manière correspondant à « {a} ».","{fr2Adverb(a)}",[("{a}","adj"),("{fr2Adverb(a)+'s'}","accord"),("{a+'ment'}","base")],["L’adverbe décrit comment l’action se réalise et reste invariable.","La forme est {answer}."],vars={"a":{"pick":["lent","doux","heureux","prudent","patient"]}},where=["fr2Adverb(a) != a+'ment'"],misc=[("adj","Tu as gardé l’adjectif au lieu de former l’adverbe."),("accord","L’adverbe est invariable ; ne lui ajoute pas un pluriel."),("base","Vérifie la base et la graphie particulière avant d’ajouter la terminaison.")],sources=["francais"],lang="fr")})

vocab(26,"Homophones : ver, vers, verre et vert",
 "Des homophones se prononcent de la même façon dans le modèle étudié mais ont des graphies et des sens différents. Ver nomme un animal ; vers peut être une préposition de direction ; verre désigne un matériau ou un récipient ; vert est notamment un adjectif de couleur. D’autres sens existent, comme un vers de poésie. La phrase et la catégorie grammaticale permettent de choisir la graphie.",
 "Bih voit un ver près du jardin. Ayuk marche vers la porte. Un verre reste sur la table. Le tissu est vert. Un remplacement guidé seulement par le son produirait des phrases incohérentes ; il faut comprendre la relation et l’objet nommé.",[
 ("ver","le nom d’un animal dans le modèle","Un ver remue dans la terre du jardin.","L’animal du modèle s’écrit nécessairement verre.","Ver nomme ici l’animal."),("vers","la préposition indiquant une direction dans le modèle","Ayuk se dirige vers la porte.","Vers indiquant une direction doit prendre un t final.","La préposition s’écrit vers."),("verre","le nom du récipient ou du matériau dans le modèle","Le verre contient de l’eau.","Le récipient du modèle s’écrit ver.","Le récipient s’écrit verre."),("vert","l’adjectif de couleur au masculin singulier","Le tissu vert est posé sur la table.","L’adjectif de couleur vert est toujours la préposition vers.","La fonction et le sens distinguent vert de vers.")])

unit(27,"Le futur simple",
 "Le futur simple évoque notamment une action à venir par rapport au moment où l’on parle. Les terminaisons sont -ai, -as, -a, -ons, -ez, -ont. Beaucoup de verbes gardent l’infinitif comme base ; les verbes en -re perdent le e final et certains ont un radical particulier. Ne confonds pas le futur simple avec le futur proche formé avec aller au présent et l’infinitif. Un futur exprime un projet ou une perspective, pas une garantie que tout se réalisera.",
 "Pour un projet de club, Bih dit : demain, {fr2With(4,fr2FuturSimple('travailler',4))}. Avec aller, la base change : {fr2With(4,fr2FuturSimple('aller',4))}. Compare la même personne pour comprendre que la terminaison reste liée au sujet alors que le radical varie selon le verbe.",
 "Repère le sujet, choisis la base du futur et ajoute la terminaison. Vérifie les radicaux particuliers. Distingue notamment -ai du futur et -ais du conditionnel pour je lorsque le contexte demande le futur simple.",[
 F("projection future","la présentation d’un fait à venir depuis le présent","Demain situe le projet du club après le moment de parole.","Tout futur constitue une preuve que l’événement a déjà eu lieu.","Il présente ici une perspective à venir."),F("radical du futur","la base portant les terminaisons du futur","Pour aller, le modèle donne {fr2FutureStem('aller')}.","Aller conserve obligatoirement aller- au futur simple.","Aller a le radical particulier ir-."),F("terminaison personnelle","la finale liée au sujet du verbe au futur","Avec nous, travailler donne {fr2FuturSimple('travailler',4)}.","Nous au futur prend toujours -ont.","Nous prend -ons ; -ont appartient à ils ou elles."),F("futur proche","la construction aller au présent suivi d’un infinitif","{fr2FuturProche('travailler',4)} n’est pas une forme simple.","Le futur proche et le futur simple sont toujours construits exactement de la même façon.","Le futur proche comporte aller au présent et un infinitif.")],replacement={2:conjugation(27,"fr2FuturSimple","futur simple",["travailler","finir","aller","faire"])})

vocab(28,"Hygiène et salubrité : les mots des gestes quotidiens",
 "L’hygiène désigne des pratiques qui contribuent à préserver la santé. La salubrité concerne notamment les conditions favorables à la santé dans un milieu. On peut décrire le lavage des mains à l’eau et au savon, la gestion appropriée des déchets et l’entretien des lieux. Propre à l’œil ne veut pas dire exempt de tous les risques. Le cours apprend le vocabulaire et ne remplace pas les consignes sanitaires locales ou les conseils professionnels.",
 "Dans une préparation fictive, le club identifie le point d’eau, les consignes de dépôt des déchets et les tâches autorisées par l’enseignante. Il évite de manipuler des objets coupants ou inconnus. Le texte distingue un geste d’hygiène personnel de l’organisation d’un milieu plus salubre, sans promettre une absence totale de maladie.",[
 ("hygiène","des pratiques contribuant à préserver la santé","Un texte décrit le lavage des mains à l’eau et au savon.","L’hygiène garantit qu’aucune maladie n’est jamais possible.","Elle contribue à la prévention sans offrir de garantie absolue."),("salubrité","des conditions d’un milieu favorables à la santé","Le club examine les conditions de propreté et de gestion des déchets d’un lieu.","La salubrité concerne uniquement la couleur des vêtements.","Elle porte sur les conditions du milieu."),("déchet","une matière ou un objet dont on se défait","Un papier usagé rejoint le dépôt prévu par l’école.","Tout déchet inconnu doit être touché à mains nues par les élèves.","Respecte les consignes et ne manipule pas les objets dangereux ou inconnus."),("consigne sanitaire","une instruction appropriée concernant la protection de la santé","L’enseignante explique quelles tâches sont autorisées.","Une phrase de vocabulaire remplace toute consigne locale.","Le vocabulaire aide à comprendre les consignes, sans les remplacer.")])

vocab(30,"Protéger l’environnement : choisir des verbes précis",
 "Protéger un milieu demande de comprendre les actions décrites. Réduire évite une partie des déchets à la source ; réutiliser donne un nouvel usage à un objet approprié ; recycler transforme une matière par une filière adaptée ; préserver cherche à maintenir un milieu ou une ressource. Ces verbes ne sont pas interchangeables. Le tri dépend des installations locales : mettre un objet dans un panier ne prouve pas qu’il sera effectivement recyclé.",
 "Dans un projet scolaire fictif, Bih propose d’éviter les feuilles inutiles. Ayuk réemploie une boîte propre pour ranger du matériel. L’enseignante vérifie quelles matières une filière locale accepte. Le groupe respecte les plantes du jardin. Chacune de ces actions porte un sens différent et doit rester adaptée aux consignes de l’école.",[
 ("réduire","diminuer la quantité utilisée ou produite à la source","Le club évite des feuilles inutiles.","Réduire signifie nécessairement produire davantage de déchets.","Le but est de diminuer la quantité à la source."),("réutiliser","employer à nouveau un objet approprié","Une boîte propre sert ensuite au rangement.","Toute réutilisation exige de transformer la matière industriellement.","Un nouvel usage peut conserver l’objet."),("recycler","transformer une matière par une filière appropriée","Une matière acceptée est orientée vers une filière de transformation.","Trier un objet prouve automatiquement qu’il est recyclé.","Le recyclage dépend d’une filière effective."),("préserver","maintenir un milieu ou une ressource en évitant sa dégradation","Les élèves respectent les plantations du jardin.","Préserver un jardin signifie obligatoirement l’abîmer.","La préservation vise à éviter sa dégradation.")])

unit(31,"Traduction : les adverbes de manière",
 "Traduire demande de comprendre le sens de la phrase, pas seulement de remplacer chaque mot isolé. L’adverbe de manière anglais et son équivalent français n’ont pas nécessairement la même construction. En français, l’adverbe reste invariable. Lis le verbe et l’intention avant de choisir. Une traduction peut avoir plusieurs formulations correctes ; les modèles de cette leçon donnent des équivalents usuels, sans prétendre exclure tout synonyme adapté.",
 "Exemples de traduction : slowly → {fr2Adverb('lent')}, politely → {fr2Adverb('poli')}, carefully → avec soin, happily → {fr2Adverb('heureux')}. Avec soin est une locution adverbiale : une expression peut rendre un seul mot. Il ne faut pas fabriquer un mot inexistant pour conserver le même nombre de mots.",
 "Détermine comment l’action se réalise, propose l’équivalent et relis toute la phrase française. Vérifie les accords éventuels ailleurs dans la phrase sans accorder l’adverbe. Distingue adjectif et adverbe ; une traduction doit être correcte dans les deux langues.",[
 F("équivalence de sens","la conservation de l’idée pertinente plutôt que des lettres du mot source","Slowly peut être rendu par {fr2Adverb('lent')}.","Traduire oblige à conserver exactement les mêmes lettres.","Les langues utilisent des formes différentes pour une idée proche."),F("locution adverbiale","un groupe de mots jouant le rôle d’un adverbe","Carefully peut être rendu par avec soin.","Un mot anglais doit toujours devenir exactement un mot français.","Une expression peut rendre le sens d’un mot."),F("contexte verbal","l’action dont la manière doit être traduite","Le lecteur examine le verbe associé à politely.","L’adverbe se traduit toujours sans lire la phrase.","La construction et le contexte peuvent modifier le choix."),F("invariabilité de l’adverbe","l’absence d’accord de l’adverbe français avec le sujet","Politely correspond ici à {fr2Adverb('poli')} quel que soit le nombre du sujet.","Tous les adverbes français prennent un s quand le sujet est pluriel.","L’adverbe ne reçoit pas cet accord.")],replacement={2:B.QA("fr3-31-traduire",2,"{X.q}",[
 dict(q="Choisis l’équivalent de slowly dans ce modèle.",r="{fr2Adverb('lent')}",w=["lent","vite","{fr2Adverb('lent')+'s'}"],e=["Lent est un adjectif ; ici il faut la manière.","Vite inverse la manière exprimée.","L’adverbe ne prend pas de pluriel."],y="Slowly exprime la lenteur de l’action."),
 dict(q="Choisis l’équivalent de politely dans ce modèle.",r="{fr2Adverb('poli')}",w=["poli","brutalement","{fr2Adverb('poli')+'s'}"],e=["Poli est l’adjectif, pas l’adverbe demandé.","Cette manière ne conserve pas la courtoisie exprimée.","L’adverbe reste invariable."],y="Politely décrit une manière courtoise."),
 dict(q="Choisis l’équivalent de carefully dans le modèle proposé.",r="avec soin",w=["sans soin","négligemment","soigneux"],e=["Sans soin inverse la manière.","Négligemment n’exprime pas le soin demandé.","Soigneux est un adjectif ; une locution de manière convient ici."],y="Une locution peut rendre un adverbe anglais.")],["francais"])})

